import{_ as i,l as r,o as e,c as s,v as l,p as d,x as t,d as n,i as c,S as C}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"DPLL 与 CDCL","description":"","frontmatter":{"title":"DPLL 与 CDCL","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dpll-cdcl.md","filePath":"cs/dpll-cdcl.md","lastUpdated":1789023840000}'),p={name:"cs/dpll-cdcl.md"};function D(h,a,A,L,S,T){const o=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=l('<h1 id="dpll-与-cdcl" tabindex="-1">DPLL 与 CDCL <a class="header-anchor" href="#dpll-与-cdcl" aria-label="Permalink to &quot;DPLL 与 CDCL&quot;">​</a></h1><div class="epigraph"><p>DPLL：单位传播、纯文字、分裂。CDCL 在冲突上做子句学习与非时序回溯，现代 SAT 求解器靠这一循环吃下工业 CNF。</p><footer>—— 据 Davis, Putnam, Logemann and Loveland, 1962；Marques-Silva and Sakallah；Biere et al., Handbook of Satisfiability 整理</footer></div><p>上一课<a href="/cs/ltl-ctl">LTL/CTL</a> 的有界路径会编成 SAT。主干<a href="/cs/sat-3sat">SAT/3-SAT</a> 只谈完全性。缺口是<strong>求解</strong>：DPLL 与 CDCL。不重证 NPC，不保证多项式——只保证可靠完备的搜索。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CNF。单位子句强迫赋值（BCP）。纯文字可定。否则选变元分裂。冲突则回溯。CDCL：分析冲突蕴含图，学一条切割子句，跳回该子句的第二高决策层（非时序）。重启、活动启发式（VSIDS）是工程。2-SAT 线性；一般 CNF 指数最坏，实践远好于真值表。</p><p>Tseitin 课的等可满足 CNF 是输入形态。求解器不管原公式树。</p><h3 id="学习不是机器学习" tabindex="-1">学习不是机器学习 <a class="header-anchor" href="#学习不是机器学习" aria-label="Permalink to &quot;学习不是机器学习&quot;">​</a></h3><p>学的是逻辑后承子句，可靠。启发式才是经验。不要把 SAT 求解写成训练。</p><p><span class="marginnote">DP 1960、DLL 1962。GRASP、Chaff 开创 CDCL。Handbook of Satisfiability。本课不把 DRAT 证明日志写完，点名：可独立校验。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用 4 子句小例子走一遍单位传播到冲突，画蕴含图，学一条子句。对照归结：学习子句是归结的压缩。指出：有界模型检验把 \\(k\\) 加大，反复调用同一引擎。</p>',11)),(e(),d(C,null,{default:t(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CNF%5B%22CNF%22%5D%20--%3E%20BCP%5B%22%E5%8D%95%E4%BD%8D%E4%BC%A0%E6%92%AD%22%5D%0A%20%20BCP%20--%3E%20DEC%5B%22%E5%86%B3%E7%AD%96%E5%88%86%E8%A3%82%22%5D%0A%20%20DEC%20--%3E%20CFL%5B%22%E5%86%B2%E7%AA%81%22%5D%0A%20%20CFL%20--%3E%20LEARN%5B%22%E5%AD%A6%E5%AD%90%E5%8F%A5%20%2F%20%E5%9B%9E%E6%BA%AF%22%5D%0A%20%20LEARN%20--%3E%20BCP%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>NP 证书是赋值；求解器找证书或证 UNSAT（后者是 coNP 对象，靠学习子句推导 \\(\\bot\\)）。CDCL 把<a href="/cs/cook-levin">Cook–Levin</a> 的「难」留在最坏，工业实例有结构。SMT 下一课在 CDCL 外挂理论传播。</p><p>完备：无限内存、无重启公平性条件下可穷尽。实践有时限。</p><p>VSIDS 给最近冲突的变元加分，重启清空决策但保留学习子句。DRAT/LRAT 让 UNSAT 可独立校验，对应 coNP 证书的工程版。相位保存、子句删除策略决定内存。有界模型检验里 \\(k\\) 增大则 CNF 变长，同一引擎反复跑。最坏仍指数，NPC 未崩。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写手表启发式全文，不引入 MaxSAT。不把量子退火当 SAT。后课默认：命题核是 CDCL。下一课理论组合：SMT。</p><p>单位传播加冲突学习把工业 CNF 变成可解实践，最坏仍指数。UNSAT 靠推导空子句，并可外挂证明日志。理论原子下一课交给 SMT，布尔核仍是本课循环。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DPLL = 传播 + 分裂；CDCL 加冲突学习与非时序回溯。</li><li>可靠完备搜索，不是多项式算法。</li><li>有界模型检验与验证条件都交给它。</li><li>出处：Davis et al., 1962；Marques-Silva and Sakallah；Handbook of Satisfiability。</li></ul>',9))])}const f=i(p,[["render",D]]);export{_ as __pageData,f as default};
